#!/usr/bin/env python3
"""Generate an isolated, unintegrated Blockbench draft. Requires Pillow."""
from pathlib import Path
import base64, io, json, math, random, uuid
from PIL import Image, ImageDraw

HERE = Path(__file__).resolve().parent

def uid(s):
    return str(uuid.uuid5(uuid.NAMESPACE_URL, 'elytrix-kaneki-draft:' + s))

# A deliberately pixel-art texture, drawn locally rather than generated by an AI.
rng = random.Random(1931)
im = Image.new('RGBA', (64, 64), (96, 0, 5, 255))
pix = im.load()
for y in range(64):
    for x in range(64):
        stripe = ((x + y // 3) % 16)
        base = 105 + (38 if 2 <= stripe <= 5 else 0) + (18 if stripe == 8 else 0)
        noise = rng.randrange(-15, 16)
        pix[x, y] = (max(35, min(230, base + noise)), max(0, 2 + noise // 3), max(0, 7 + noise // 2), 255)
draw = ImageDraw.Draw(im)
for x in (4, 18, 35, 51):
    draw.line([(x, 0), (x+4, 20), (x-1, 45), (x+2, 63)], fill=(205, 8, 14, 255), width=1)
buf = io.BytesIO(); im.save(buf, format='PNG', optimize=True)
texture = {'path':'', 'name':'elytrix_kaneki_tentacles.png', 'folder':'', 'namespace':'', 'id':'0',
           'width':64, 'height':64, 'uv_width':16, 'uv_height':16, 'particle':False,
           'use_as_default':False, 'layers_enabled':False, 'render_mode':'default', 'render_sides':'auto',
           'frame_time':1, 'frame_order_type':'loop', 'frame_interpolate':False, 'visible':True,
           'internal':True, 'saved':False, 'uuid':uid('texture'),
           'source':'data:image/png;base64,' + base64.b64encode(buf.getvalue()).decode('ascii')}

def bone(name, origin, children):
    return {'name':name, 'origin':origin, 'rotation':[0,0,0], 'color':0, 'uuid':uid('bone:'+name),
            'export':True, 'mirror_uv':False, 'isOpen':True, 'locked':False, 'visibility':True,
            'autouv':0, 'children':children}

# Four separately placed arms, based on the supplied silhouette.  The z
# component increases away from the player's back: arms do not share a plane.
# Angles are constrained to vanilla's -45/-22.5/0/22.5/45 degree rotations.
c=0.41421356237
paths={
 'left_upper': [(-0.8,18.6,4.7),(-7.0,12.4,5.1),(-14.0,12.4+7*c,5.6),(-20.0,18.4+7*c,6.0),(-20.0,28.3,6.4),(-18.0,28.3+2/c,6.8)],
 'right_upper':[(0.9,19.0,5.2),(6.7,13.2,5.6),(13.2,13.2+6.5*c,6.1),(19.0,19.0+6.5*c,6.5),(19.0,29.4,6.9),(17.4,29.4+1.6/c,7.2)],
 'left_lower':[(-0.5,16.5,5.0),(-6.7,10.3,5.4),(-13.7,10.3-7*c,5.9),(-19.5,10.3-7*c,6.3),(-23.5,10.3-3*c,6.7),(-27.5,10.3-3*c,7.1)],
 'right_lower':[(0.7,16.4,5.5),(7.1,10.0,5.9),(12.1,5.0,6.4),(18.6,5.0,6.8),(23.6,5.0+5*c,7.2),(26.6,8.0+5*c,7.6)],
}
elements=[]; arms=[]; paths_for_preview=[]
for name,path in paths.items():
    children=[]
    for i,(a,b) in enumerate(zip(path,path[1:])):
        dx,dy=b[0]-a[0],b[1]-a[1]; length=math.hypot(dx,dy)
        angle=math.degrees(math.atan2(dy,dx))
        while angle > 90:angle-=180
        while angle < -90:angle+=180
        vertical=abs(angle)>45.01
        if vertical: angle-=math.copysign(90,angle)
        nearest=round(angle/22.5)*22.5
        assert abs(angle-nearest)<0.02 and abs(nearest)<=45, (name,i,angle)
        center=[(a[0]+b[0])/2,(a[1]+b[1])/2,(a[2]+b[2])/2]
        # A broad root tapers to a pointed end, like the segmented reference.
        width=max(1.45,4.7-i*0.62)
        if vertical:
            p0=[center[0]-width/2,center[1]-length/2-0.48,center[2]-width/2]
            p1=[center[0]+width/2,center[1]+length/2+0.48,center[2]+width/2]
        else:
            p0=[center[0]-length/2-0.48,center[1]-width/2,center[2]-width/2]
            p1=[center[0]+length/2+0.48,center[1]+width/2,center[2]+width/2]
        eid=uid(f'cube:{name}:{i}');children.append(eid)
        faces={face:{'uv':[0,0,16,16],'texture':0} for face in ('north','south','east','west','up','down')}
        elements.append({'name':f'{name}_{i+1}', 'box_uv':False, 'rescale':False, 'locked':False,
            'light_emission':0, 'render_order':'default','allow_mirror_modeling':True,
            'from':[round(v,4) for v in p0], 'to':[round(v,4) for v in p1], 'autouv':0, 'color':0,
            'origin':[round(v,4) for v in center], 'rotation':[0,0,nearest], 'faces':faces, 'type':'cube','uuid':eid})
    arms.append(bone(name,list(path[0]),children));paths_for_preview.append([(x,y) for x,y,z in path])
root=bone('tentacles_root',[0,20,0],arms)

def key(name,t,z):
    return {'channel':'rotation','data_points':[{'x':'0','y':'0','z':str(z)}],
            'uuid':uid(f'key:{name}:{t}'),'time':t,'color':-1,'interpolation':'linear'}
animators={}
for i, arm in enumerate(arms):
    sign = -1 if i%2==0 else 1
    # Sample a full sine cycle at quarter-second intervals. Piecewise-linear
    # interpolation between closely spaced samples avoids abrupt reversals.
    frames=[key(arm['name'],step/4,round(sign*4*math.sin(math.pi*step/12+i*0.55),4)) for step in range(25)]
    frames[-1]['data_points']=frames[0]['data_points']
    animators[arm['uuid']]={'name':arm['name'],'type':'bone','keyframes':frames}
model={'meta':{'format_version':'4.10','model_format':'free','box_uv':False},
       'name':'elytrix_kaneki_tentacles','model_identifier':'elytrix_kaneki_tentacles',
       'visible_box':[5,5,1], 'resolution':{'width':16,'height':16}, 'elements':elements,
       'outliner':[root], 'textures':[texture], 'animations':[{'uuid':uid('idle'), 'name':'idle', 'loop':'loop',
       'override':False, 'length':6, 'snapping':20, 'selected':True,'anim_time_update':'',
       'blend_weight':'','start_delay':'','loop_delay':'','animators':animators}]}
(HERE/'elytrix_kaneki_tentacles.bbmodel').write_text(json.dumps(model,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
# Schematic rear view only; it is not a Minecraft render.
preview=Image.new('RGB',(720,520),(22,28,42)); d=ImageDraw.Draw(preview)
def xy(p): return (360+p[0]*9, 420-p[1]*9)
for path in paths_for_preview:
    points=[xy(p) for p in path]
    d.line(points,fill=(55,0,4),width=32,joint='curve')
    d.line(points,fill=(142,3,10),width=24,joint='curve')
    d.line([(x-3,y-3) for x,y in points],fill=(218,18,25),width=3,joint='curve')
# Human silhouette indicates scale only.
d.rectangle((324,204,396,310),fill=(196,201,209)); d.rectangle((323,132,397,205),fill=(75,79,91))
d.rectangle((294,205,323,311),fill=(174,180,191)); d.rectangle((397,205,426,311),fill=(174,180,191))
d.rectangle((326,311,357,410),fill=(84,88,100)); d.rectangle((363,311,394,410),fill=(84,88,100))
d.text((14,12),'SCHEMATIC REAR VIEW  -  NOT AN IN-GAME RENDER', fill=(220,220,230))
preview.save(HERE/'kaneki_schematic.png')
print('Generated',len(elements),'cubes,',len(arms),'tentacles')
